88		}
89		s2, err := Open(dir)
90		if err != nil {
91			t.Fatalf("reopen: %v", err)
92		}
93		defer s2.Close()
94		if got := s2.points["P3"]; got.ID != "P3" || got.Name != "三号点" {
95			t.Fatalf("重开后成功登记的采样点异常: %+v", got)
96		}
97		if _, ok := s2.points["P2"]; ok {
98			t.Fatal("重开后失败编号不得随其它成功操作一并保存")
99		}
100		if _, err := s2.SetLimit("P2", "pH", 8.0, at(1, 0)); !errors.Is(err, ErrUnknownPoint) {
101			t.Fatalf("重开后失败编号仍应未登记，got %v", err)
102		}
103	
104		// 给失败编号加上首尾空白，填写一个与失败请求不同的合法名称：
105		// 去空白后判断的仍是同一个编号 P2，应作为首次登记成功接受，
106		// 返回的编号、名称均为去掉首尾空白后的内容，名称只来自这次成功请求。
107		p, err := s2.RegisterPoint("  P2  ", "  正式名称  ")
108		if err != nil {
109			t.Fatalf("恢复后失败编号应能首次登记成功: %v", err)
110		}
111		if p.ID != "P2" || p.Name != "正式名称" {
112			t.Fatalf("成功登记应返回去空白后的编号与本次名称，got %+v", p)
113		}
114	
115		// 现在它是能登记限值的已知采样点。
116		if _, err := s2.SetLimit(" P2 ", "pH", 8.0, at(1, 0)); err != nil {
117			t.Fatalf("成功登记后应能登记限值: %v", err)
118		}
119	
120		// 再次登记同一编号恢复现有的重复编号拒绝，成功名称不被第二次名称替换。
121		dup, err := s2.RegisterPoint("P2", "又一个名称")
122		if !errors.Is(err, ErrDuplicatePoint) {
123			t.Fatalf("成功登记后重复编号应被拒绝，got %v", err)
124		}
125		if dup.ID != "" || dup.Name != "" {
126			t.Fatalf("被拒绝的登记必须返回空采样点，got %+v", dup)
127		}
128		if got := s2.points["P2"]; got.ID != "P2" || got.Name != "正式名称" {
129			t.Fatalf("重复登记不得替换成功名称: %+v", got)
130		}
131	}
132	
133	// 数据中已经有成功登记的采样点（含限值与已确认样品）时再登记失败：
134	// 必须返回保存错误和空采样点；原采样点的编号、名称不变，已关联的限值和
135	// 样品仍归属于它，按点查询看到的样品与已保存判定依据（测量值、状态、
136	// 逐项所用上限及生效时间、整份结论）保持原样，原有采样点可继续使用。
137	// 同样无法保存的条件下，提交已有编号仍返回现有的重复编号错误，不能被说成
138	// 保存失败。恢复后先成功登记别的编号并重开数据存放，失败编号仍未登记；
139	// 换一个合法名称首次登记成功后，再次登记该编号恢复重复编号拒绝。
140	func TestRegisterPointPersistFailureWithExistingPoint(t *testing.T) {
141		s, dir := open(t)
142	
143		// 一个此前成功登记、已有关联限值和已确认样品的采样点。
144		mustPoint(t, s, "P1", "一号取水口")
145		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
146		mustSample(t, s, "S1", "P1", at(10, 0), Measurement{Item: "pH", Value: 9})
147		checkPHExceededSaved(t, mustConfirm(t, s, "S1"), "前置确认")
148	
149		// 只让新采样点的保存失败：采样点、限值和样品此前均已成功落盘。
