151		if err := os.Mkdir(tmp, 0o755); err != nil {
152			t.Fatalf("block persist: %v", err)
153		}
154	
155		// 合法的新编号登记走到保存阶段后失败：保存错误 + 空采样点。
156		assertRegisterSaveFailure(t, s, "已有数据时新编号登记失败", "P2", "二号取水口")
157	
158		// 失败编号没有被占用，也不能登记限值。
