179		list, err := s.ListByPoint("P1")
180		if err != nil || len(list) != 1 || list[0].ID != "S1" {
181			t.Fatalf("失败登记后按点查询变化: %+v err=%v", list, err)
182		}
183		checkPHExceededSaved(t, list[0], "失败登记后按点查看")
184		// 原样品的测量值、状态、所用上限不受影响：重复确认仍返回原判定。
185		checkPHExceededSaved(t, mustConfirm(t, s, "S1"), "失败登记后重复确认")
186		latest, ok, err := s.LatestResult("P1")
187		if err != nil || !ok {
188			t.Fatalf("原采样点最近有效结果查询失败: ok=%v err=%v", ok, err)
189		}
190		checkPHExceededSaved(t, latest, "失败登记后最近有效结果")
191		// 失败编号下查不到任何样品。
192		if list2, err := s.ListByPoint("P2"); err != nil || len(list2) != 0 {
193			t.Fatalf("失败编号下不应有样品，got %+v err=%v", list2, err)
194		}
195	
196		// 保存失败与内容校验失败明确区分：同样无法保存时，提交已有编号仍在保存
197		// 之前的校验阶段返回现有的重复编号错误，不能被说成保存失败；
198		// 去首尾空白的规则继续适用，" P1 " 判断的仍是 P1。
199		for _, id := range []string{"P1", " P1 "} {
200			got, err := s.RegisterPoint(id, "完全不同的名称")
201			if !errors.Is(err, ErrDuplicatePoint) {
202				t.Fatalf("已有编号 %q 在无法保存时仍应报重复编号，got %v", id, err)
203			}
204			if got.ID != "" || got.Name != "" {
205				t.Fatalf("重复编号登记必须返回空采样点，got %+v", got)
206			}
207		}
208		// 空字段同样先于保存被拒绝，不冒充保存失败。
209		if _, err := s.RegisterPoint("P9", "   "); !errors.Is(err, ErrEmptyField) {
210			t.Fatalf("空白名称应报空字段错误，got %v", err)
211		}
212		// 校验被拒绝不改变任何状态。
213		if got := s.points["P1"]; got.Name != "一号取水口" {
214			t.Fatalf("重复编号登记不得改动原采样点名称: %+v", got)
215		}
216		if _, ok := s.points["P9"]; ok {
217			t.Fatal("空字段登记不得留下采样点")
218		}
219	
220		// 恢复正常保存条件。
221		if err := os.Remove(tmp); err != nil {
222			t.Fatalf("restore persist: %v", err)
223		}
224	
225		// 原有采样点继续使用：新增另一项目的限值、再录一份样品都正常。
226		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
227		mustSample(t, s, "S2", "P1", at(11, 0), Measurement{Item: "pH", Value: 6})
228		// 此前的已确认样品判定依据依旧不变。
229		checkPHExceededSaved(t, mustConfirm(t, s, "S1"), "恢复后原样品判定")
230	
231		// 调用方先成功登记另一个编号，不能把失败的 P2 顺带保存。
232		if p, err := s.RegisterPoint("P3", "三号点"); err != nil || p.ID != "P3" || p.Name != "三号点" {
233			t.Fatalf("恢复后登记其它编号异常: %+v err=%v", p, err)
234		}
235		if _, ok := s.points["P2"]; ok {
236			t.Fatal("别的成功登记不得顺带写入失败编号")
237		}
238	
239		// 关闭后重新打开同一数据存放：原采样点及其限值、样品判定原样，
240		// P3 已保存，失败的 P2 仍是未登记状态。
241		if err := s.Close(); err != nil {
242			t.Fatalf("Close: %v", err)
243		}
244		s2, err := Open(dir)
245		if err != nil {
246			t.Fatalf("reopen: %v", err)
247		}
