249		if got := s2.points["P1"]; got.ID != "P1" || got.Name != "一号取水口" {
250			t.Fatalf("重开后原采样点变化: %+v", got)
251		}
252		if got := s2.points["P3"]; got.ID != "P3" || got.Name != "三号点" {
