257		}
258		reopened, err := s2.ListByPoint("P1")
259		if err != nil || len(reopened) != 2 {
260			t.Fatalf("重开后按点查询变化: %+v err=%v", reopened, err)
261		}
262		var reopenedS1 *Sample
263		for i := range reopened {
264			if reopened[i].ID == "S1" {
265				reopenedS1 = &reopened[i]
266			}
267		}
268		if reopenedS1 == nil {
269			t.Fatalf("重开后原样品 S1 丢失: %+v", reopened)
270		}
271		// 原样品的测量值、状态、所用上限保持原样。
272		checkPHExceededSaved(t, *reopenedS1, "重开后原已确认样品")
273		if _, err := s2.SetLimit("P2", "pH", 1.0, at(1, 0)); !errors.Is(err, ErrUnknownPoint) {
274			t.Fatalf("重开后失败编号仍应报采样点未登记，got %v", err)
275		}
276	
277		// 用失败过的编号、填写一个与失败请求不同的合法名称，作为首次登记成功接受；
278		// 返回的名称只来自这次成功请求，而不是失败时填写的“二号取水口”。
279		p, err := s2.RegisterPoint("P2", "  正式二号点  ")
280		if err != nil {
281			t.Fatalf("恢复后失败编号应能首次登记成功: %v", err)
282		}
