// validateLoadedSample 校验一份从本地文件读入、带有判定结论的样品记录：
// 已确认样品，以及已确认后作废、Results 中仍保留历史依据的样品，其原测量
// 项目与逐项判定必须按项目名一一对应——至少一个测量项目；原测量和判定中同一
// 项目都不能出现两次；每个测量项目必须且只能有一条判定记录，判定中也不能出现
// 原测量没有的项目；对应项目的判定测量值必须与原测量值逐位一致（零是合法
// 测量值，按 map 中是否存在该项目判断，不把零当成缺项）。项目按名称对应，
// 与两个列表的排列顺序无关。待判定样品与待判定后作废（没有历史依据）的样品
// 不带逐项判定，属于正常情况，不在此校验之列。
func validateLoadedSample(smp *Sample) error {
	if smp.Status != StatusConfirmed && len(smp.Results) == 0 {
		return nil
	}
	if len(smp.Measurements) == 0 {
		return fmt.Errorf("%w: 样品 %s 没有测量项目", ErrCorruptRecord, smp.ID)
	}
	meas := make(map[string]float64, len(smp.Measurements))
	for _, m := range smp.Measurements {
		if _, ok := meas[m.Item]; ok {
			return fmt.Errorf("%w: 样品 %s 的测量项目 %s 重复", ErrCorruptRecord, smp.ID, m.Item)
		}
		meas[m.Item] = m.Value
	}
	got := make(map[string]float64, len(smp.Results))
	for _, r := range smp.Results {
		if _, ok := got[r.Item]; ok {
			return fmt.Errorf("%w: 样品 %s 的项目 %s 判定记录重复", ErrCorruptRecord, smp.ID, r.Item)
		}
		got[r.Item] = r.Value
	}
	// 缺项或判定测量值与原测量不一致（按测量列表顺序报告，保持信息稳定）。
	for _, m := range smp.Measurements {
		rv, ok := got[m.Item]
		if !ok {
			return fmt.Errorf("%w: 样品 %s 缺少项目 %s 的判定记录", ErrCorruptRecord, smp.ID, m.Item)
		}
		if rv != m.Value {
			return fmt.Errorf("%w: 样品 %s 的项目 %s 判定测量值 %g 与原测量值 %g 不一致",
				ErrCorruptRecord, smp.ID, m.Item, rv, m.Value)
		}
	}
	// 判定中出现原测量没有的项目。
	for _, r := range smp.Results {
		if _, ok := meas[r.Item]; !ok {
			return fmt.Errorf("%w: 样品 %s 的判定记录出现了原测量中没有的项目 %s",
				ErrCorruptRecord, smp.ID, r.Item)
		}
	}
	return nil
}

