			return fmt.Errorf("%w: 样品 %s 的测量项目 %s 重复", ErrCorruptRecord, smp.ID, m.Item)
		}
		meas[m.Item] = m.Value
	}
	got := make(map[string]float64, len(smp.Results))
	for _, r := range smp.Results {
		if _, ok := got[r.Item]; ok {
			return fmt.Errorf("%w: 样品 %s 的项目 %s 判定记录重复", ErrCorruptRecord, smp.ID, r.Item)
		}
		got[r.Item] = r.Value
	}
