	for _, m := range smp.Measurements {
		rv, ok := got[m.Item]
		if !ok {
			return fmt.Errorf("%w: 样品 %s 缺少项目 %s 的判定记录", ErrCorruptRecord, smp.ID, m.Item)
		}
		if rv != m.Value {
			return fmt.Errorf("%w: 样品 %s 的项目 %s 判定测量值 %g 与原测量值 %g 不一致",
				ErrCorruptRecord, smp.ID, m.Item, rv, m.Value)
